export const speciesBySlug: Readonly<Record<string, Species>> = Object.fromEntries(
  species.map((item) => [item.slug, item]),
);

export const featuredSpecies: readonly Species[] = species.filter((item) => item.featured);

export const getSpeciesBySlug = (slug: string): Species | undefined => speciesBySlug[slug];

export const getSpeciesById = (id: string): Species | undefined =>
  species.find((item) => item.id === id);
